function valid_date(date){
    // Check if the date string is empty
    if (date === '') {
        return false;
    }

    // Split the date string into month, day, and year
    const parts = date.split('-');

    // Check if the date string has exactly three parts
    if (parts.length !== 3) {
        return false;
    }

    // Extract the month, day, and year from the parts
    const month = parseInt(parts[0], 10);
    const day = parseInt(parts[1], 10);
    const year = parseInt(parts[2], 10);

    // Check if the month is between 1 and 12
    if (month < 1 || month > 12) {
        return false;
    }

    // Check if the day is between 1 and 31 for months 1, 3, 5, 7, 8, 10, 12
    if (month in [1, 3, 5, 7, 8, 10, 12] && day < 1 || day > 31) {
        return false;
    }

    // Check if the day is between 1 and 30 for months 4, 6, 9, 11
    if (month in [4, 6, 9, 11] && day < 1 || day > 30) {
        return false;
    }

    // Check if the day is between 1 and 29 for the month 2 (if the year is a leap year)
    if (month === 2) {
        const isLeapYear = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
        if (!isLeapYear && day > 29) {
            return false;
        }
    }

    // If all checks pass, the date is valid
    return true;
}

function valid_date(date) {
    // Split the date string into month, day, and year
    const parts = date.split('-');
    const month = parseInt(parts[0], 10);
    const day = parseInt(parts[1], 10);
    const year = parseInt(parts[2], 10);

    // Check if the date string is not empty
    if (isNaN(month) || isNaN(day) || isNaN(year)) {
        return false;
    }

    // Check if the month is between 1 and 12
    if (month < 1 || month > 12) {
        return false;
    }

    // Check if the day is between 1 and 31 for valid months
    if ((month === 4 || month === 6 || month === 9 || month === 11) && day < 1 || day > 30) {
        return false;
    }

    // Check if the day is between 1 and 29 for February
    if (month === 2 && day < 1 || day > 29) {
        return false;
    }

    // Check if the day is between 1 and 31 for other months
    if ((month !== 4 && month !== 6 && month !== 9 && month !== 11) && day < 1 || day > 31) {
        return false;
    }

    // If all checks pass, the date is valid
    return true;
}

