  let stack = [];
  let currentGroup = '';

  for (const char of paren_string.replace(/\s/g, '')) {
    if (char === '(') {
      stack.push(char);
      currentGroup += char;
    } else if (char === ')') {
      stack.pop();
      currentGroup += char;
