        let max_depth = 0;
        let current_depth = 0;
        for (const char of group) {
            if (char === '(') {
                current_depth++;
                max_depth = Math.max(max_depth, current_depth);
            } else if (char === ')') {
                current_depth--;
            }
        }
        return max_depth;
    });
}

