function rotate_right(list, m) {
  // Get the length of the array
  let n = list.length;

  // Perform the rotation
  for (let i = 0; i < m; i++) {
    // Get the last element of the array
    let last = list[n - 1];

    // Shift all elements in the array one position to the right
    for (let j = n - 2; j >= 0; j--) {
      list[j + 1] = list[j];
    }

    // Place the last element at the beginning of the array
    list[0] = last;
  }

  return list;
}

