  for (let i = 1; i < l.length; i++) {
    if (l[i] > max) {
      max = l[i]; // Update max if a larger element is found
    }
  }
  return max;
}

function prime_fib(n) {
  let count = 0;
  let num1 = 0, num2 = 1, fib = num1 + num2;

  while (count < n) {
    if (isPrime(fib)) {
      count++;
      if (count === n) return fib;
    }
    num1 = num2;
    num2 = fib;
    fib = num1 + num2;
  }

  function isPrime(num) {
    if (num <= 1) return false;
    for (let i = 2; i * i <= num; i++) {
      if (num % i === 0) return false;
    }
    return true;
  }
}

function prime_fib(n) {
  function is_prime(num) {
    for (let i = 2, s = Math.sqrt(num); i <= s; i++)
      if (num % i === 0) return false;
    return num > 1;
  }

  let fib_num = 0, a = 0, b = 1, count = 0;

  while (count < n) {
    fib_num = a + b;
    a = b;
    b = fib_num;

    if (is_prime(fib_num)) {
      count++;
    }
  }

  return fib_num;
}

