function is_happy(s) {
  // Check if the string length is at least 3
  if (s.length < 3) {
    return false;
  }

  // Iterate through the string to check every 3 consecutive letters
  for (let i = 0; i <= s.length - 3; i++) {
    // Extract the current group of 3 consecutive letters
    const group = s.substring(i, i + 3);

    // Check if all letters in the group are distinct
    if (new Set(group).size !== 3) {
      return false;
    }
  }

  // If all checks pass, the string is happy
  return true;
}

