function combinations_colors(l, n) {
  const result = [];
  function helper(index, current) {
    if (current.length === n) {
      result.push([...current]);
      return;
    }
    for (let i = index; i < l.length; i++) {
      current.push(l[i]);
      helper(i, current);
      current.pop();
    }
  }
  helper(0, []);
  return result;
}

