function swap_List(newList) {
  // Create a copy of the array to avoid modifying the original list
  const temp = [...newList];

  // Swap the first and last elements
  const firstElement = temp.shift(); // Remove and return the first element
  const lastElement = temp.pop(); // Remove and return the last element
  temp.unshift(lastElement); // Add the last element at the beginning
  temp.push(firstElement); // Add the first element at the end

  return temp;
}

function swap_List(newList){
    if(newList.length === 0) return newList; // Return the list if it's empty

    // Swap the first and last elements
    let firstElement = newList[0];
    let lastElement = newList[newList.length - 1];

    // Replace the first element with the last element
    newList[0] = lastElement;

    // Replace the last element with the first element
    newList[newList.length - 1] = firstElement;

    return newList;
}

function removezero_ip(ip){
  // Split the IP address into its components
  let parts = ip.split('.');

  // Filter out any leading zeroes in each part
  let filteredParts = parts.map(part => part.replace(/^0+/, ''));

  // Join the filtered parts back into a single string
  let cleanedIp = filteredParts.join('.');

  return cleanedIp;
}

