function prime_num(num){
  // Check if the number is less than 2
  if (num < 2) {
    return false;
  }

  // Check for divisibility from 2 to the square root of the number
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      return false;
    }
  }

  // If no divisors were found, the number is prime
  return true;
}

