function reverse_Array_Upto_K(input, k){
  // Check if k is out of bounds
  if (k >= input.length) {
    throw new Error("k is out of bounds");
  }

  // Reverse the array from the start to k
  for (let i = 0; i < k / 2; i++) {
    [input[i], input[k - i - 1]] = [input[k - i - 1], input[i]];
  }

  return input;
}

function reverse_Array_Upto_K(input, k) {
  const reversedArray = input.slice(0, k).reverse();
  return reversedArray.concat(input.slice(k));
}

