function sum_Of_Subarray_Prod(arr) {
    let sum = 0;
    for (let i = 0; i < arr.length; i++) {
        let product = 1;
        for (let j = i; j < arr.length; j++) {
            product *= arr[j];
            sum += product;
        }
    }
    return sum;
}

